const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const { FakeDocument } = require('./browser-fakes.js');
const { installDetailDisclosureTemplateRuntime } = require('./workbench-detail-disclosure-runtime.js');

const scripts = process.env.WORKBENCH_SCRIPT_DIR
    || path.resolve(__dirname, '../../tools/workbench/src/main/webapp/scripts');

function loadWorkbench() {
    const workbench = {};
    installDetailDisclosureTemplateRuntime(workbench);
    const context = vm.createContext({
        URL,
        URLSearchParams,
        Promise,
        console,
        window: {},
        workbench,
        setTimeout
    });
    for (const filename of ['workbenchViews.js', 'workbenchRoutes.js', 'queryStream.js', 'workbenchApp.js']) {
        vm.runInContext(fs.readFileSync(path.join(scripts, filename), 'utf8'), context, { filename });
    }
    return context.workbench;
}

function fakeRuntime() {
    return {
        html(strings, ...values) {
            return { strings: Array.from(strings), values };
        },
        render() {}
    };
}

function visitTemplates(value, templates = [], dynamicValues = []) {
    if (Array.isArray(value)) {
        value.forEach(entry => visitTemplates(entry, templates, dynamicValues));
    } else if (value && Array.isArray(value.strings) && Array.isArray(value.values)) {
        templates.push(value);
        value.values.forEach(entry => {
            if (entry && (Array.isArray(entry) || Array.isArray(entry.strings))) {
                visitTemplates(entry, templates, dynamicValues);
            } else {
                dynamicValues.push(entry);
            }
        });
    }
    return { templates, dynamicValues };
}

test('configured navigation keeps labels and URLs as inert dynamic Lit values', () => {
    const workbench = loadWorkbench();
    const runtime = fakeRuntime();
    const groupLabel = 'Analysis <tools> & research';
    const itemLabel = 'Run <query> & inspect';
    const helpLabel = 'External help';
    const helpUrl = 'https://docs.example.org/help?a=1&b=2';
    const updateUrl = '/workbench/repositories/repo-1/update';
    const template = workbench.views.pageTemplate({
        viewId: 'summary', vars: [], rows: [], metadata: {}
    }, {
        basePath: '/workbench',
        repositoryId: 'repo-1',
        workbench: {
            readable: true,
            writeable: false,
            menu: [
                {
                    id: 'operations',
                    label: groupLabel,
                    icon: 'query',
                    items: [
                        { id: 'query', label: itemLabel, icon: 'query', href: 'query' },
                        { id: 'update', label: 'Apply update', icon: 'update', href: updateUrl }
                    ]
                },
                {
                    id: 'resources',
                    label: 'Resource & support',
                    icon: 'link',
                    items: [{ id: 'help', label: helpLabel, icon: 'link', href: helpUrl }]
                }
            ]
        }
    }, runtime);
    const result = visitTemplates(template);
    const staticMarkup = result.templates.map(item => item.strings.join('')).join('');

    assert.ok(staticMarkup.includes('data-workbench-menu-group='), 'configured menu groups should render');
    assert.ok(staticMarkup.includes('class="disabled"'), 'unavailable write actions should remain disabled');
    assert.ok(result.dynamicValues.includes(groupLabel), 'group labels should stay dynamic');
    assert.ok(result.dynamicValues.includes(itemLabel), 'menu labels should stay dynamic');
    assert.ok(result.dynamicValues.includes(helpLabel), 'external-link labels should stay dynamic');
    assert.ok(result.dynamicValues.includes(helpUrl), 'external URLs should stay dynamic attribute values');
    assert.ok(!result.dynamicValues.includes(updateUrl), 'disabled write actions must not expose a link target');
    assert.ok(!staticMarkup.includes('<tools>') && !staticMarkup.includes('<query>'),
        'dynamic menu text must never become executable markup');
    assert.ok(!staticMarkup.includes(helpUrl), 'dynamic URL text must not be interpolated into template markup');
    assert.ok(!result.dynamicValues.includes('Create repository'), 'only configured navigation rows should render');
    assert.ok(staticMarkup.includes('class="workbench-nav-group__label"'),
        'every menu group renders the same non-interactive label');
    assert.ok(!result.dynamicValues.some(value => String(value).includes('workbench-nav-group__chevron')),
        'short menu groups render without a disclosure chevron');
});

test('shared chevron adapter creates one decorative, accessible 16px SVG', () => {
    const workbench = loadWorkbench();
    const document = new FakeDocument();
    const button = document.createElement('button');
    const label = document.createElement('span');
    label.textContent = 'Options';
    button.appendChild(label);
    button.firstChild = label;
    document.body.appendChild(button);

    workbench.icons.decorateButton(button, 'chevron', 'Result options');
    let icons = button.querySelectorAll('svg[data-workbench-icon]');
    assert.equal(icons.length, 1);
    assert.equal(button.children[0], icons[0], 'the icon should precede the existing button label');
    assert.equal(icons[0].getAttribute('data-workbench-icon'), 'chevron');
    assert.equal(icons[0].getAttribute('aria-hidden'), 'true');
    assert.equal(icons[0].getAttribute('width'), '16');
    assert.equal(icons[0].getAttribute('height'), '16');
    assert.equal(icons[0].querySelector('path').getAttribute('d'), 'm6 9 6 6 6-6');
    assert.equal(button.getAttribute('aria-label'), 'Result options');

    workbench.icons.decorateButton(button, 'chevron', 'Result options');
    icons = button.querySelectorAll('svg[data-workbench-icon]');
    assert.equal(icons.length, 1, 'rebinding must not duplicate the shared icon');
});

test('shared detail disclosure restores keyboard access and releases dynamic observers', () => {
	const document = new FakeDocument();
	const observers = [];
	const resizeListeners = new Set();
	const window = {
		ResizeObserver: class {
			constructor(callback) {
				this.callback = callback;
				this.observed = new Set();
				this.unobserved = [];
				this.disconnected = false;
				observers.push(this);
			}
			observe(element) { this.observed.add(element); }
			unobserve(element) { this.observed.delete(element); this.unobserved.push(element); }
			disconnect() { this.disconnected = true; this.observed.clear(); }
		},
		addEventListener(type, listener) {
			if (type === 'resize') resizeListeners.add(listener);
		},
		removeEventListener(type, listener) {
			if (type === 'resize') resizeListeners.delete(listener);
		},
		getComputedStyle(element) {
			return Object.assign({
				boxSizing: 'border-box', paddingTop: '12px', paddingBottom: '12px',
				borderTopWidth: '1px', borderBottomWidth: '1px',
				marginBlockStart: '8px', marginBlockEnd: '0px', direction: 'ltr'
			}, element.style);
		},
		matchMedia() { return { matches: true }; },
		dispatchEvent() { return true; },
		requestAnimationFrame(callback) { callback(); }
	};
	const context = vm.createContext({
		URL,
		URLSearchParams,
		Promise,
		console,
		document,
		window,
		Event: class { constructor(type) { this.type = type; } },
		workbench: {}
	});
	vm.runInContext(fs.readFileSync(path.join(scripts, 'template.js'), 'utf8'), context, {
		filename: 'template.js'
	});
	const api = context.workbench.detailDisclosure;
	// Panes stay inside their card, which the shared observer watches (plan task M14.3).
	const card = document.createElement('section');
	card.className = 'query-output';
	document.body.appendChild(card);
	const track = document.createElement('div');
	track.className = 'workbench-disclosure-track';
	card.appendChild(track);
	const disclosures = ['Download', 'Options'].map((label, index) => {
		const disclosure = api.create(document, {
			id: `dynamic-${index}`, toggleId: `dynamic-toggle-${index}`,
			panelId: `dynamic-panel-${index}`, label
		});
		disclosure.toggle.getClientRects = () => [{ width: 40, height: 36 }];
		disclosure.panel.contains = () => false;
		card.appendChild(disclosure.owner);
		track.appendChild(disclosure.panel);
		const dispose = api.bind(disclosure.toggle, disclosure.panel, disclosure.owner);
		return { ...disclosure, dispose };
	});

	assert.equal(disclosures[0].panel.inert, true, 'collapsed panels should be inert');
	disclosures[0].toggle.click();
	assert.equal(disclosures[0].panel.getAttribute('aria-hidden'), 'false',
		'opening a panel should remove its collapsed accessibility state');
	assert.equal(disclosures[0].panel.inert, false,
		'opening a panel should restore keyboard access to its controls');
	disclosures[0].toggle.click();
	assert.equal(disclosures[0].panel.getAttribute('aria-hidden'), 'true');
	assert.equal(disclosures[0].panel.inert, true);

	disclosures.forEach(disclosure => disclosure.dispose());
	assert.deepEqual(Array.from(resizeListeners), [], 'the shared resize listener should be removed after the last panel');
	assert.equal(observers.length, 1, 'panels in one result should share one resize observer');
	assert.equal(observers[0].disconnected, true, 'disposing the result should release its resize observer');
	assert.ok(observers[0].unobserved.includes(card), 'the shared result card should be unobserved');
	assert.equal(disclosures[0].toggle.eventHandlers.get('click').length, 0,
		'disposing the result should detach the toggle callback');
});

test('Information renders every live value inside one shared surface', () => {
    const workbench = loadWorkbench();
    const values = [
        'information-version-sentinel',
        'information-os-sentinel',
        'information-jvm-sentinel',
        'information-user-sentinel',
        'information-used-memory-sentinel',
        'information-maximum-memory-sentinel'
    ];
    const template = workbench.views.pageTemplate({
        viewId: 'information',
        vars: ['version', 'os', 'jvm', 'user', 'memory-used', 'maximum-memory'],
        rows: [values],
        metadata: {}
    }, { basePath: '/workbench', repositoryId: '', workbench: {} }, fakeRuntime());
    const result = visitTemplates(template);
    const staticMarkup = result.templates.map(item => item.strings.join('')).join('');

    assert.match(staticMarkup, /<div id="workbench-information" class="workbench-island">/);
    assert.equal((staticMarkup.match(/class="workbench-island"/g) || []).length, 1,
        'Information should expose one shared surface');
    const sectionTemplates = result.templates.filter(item => item.strings[0].includes('<section id='));
    assert.equal(sectionTemplates.length, 3, 'the shared surface should contain all three information sections');
    for (const sectionId of ['information-application', 'information-runtime', 'information-memory']) {
        assert.ok(result.dynamicValues.includes(sectionId), `${sectionId} should remain inside the shared surface`);
    }
    assert.ok(sectionTemplates.every(item => item.values[1] !== 'workbench-island '),
        'information sections should not create nested Workbench islands');
    for (const value of values) {
        assert.ok(result.dynamicValues.includes(value), `${value} should remain visible as a live value`);
    }
});

test('Export keeps its independent defaults, preview state, and explicit unlimited timeout', () => {
    const workbench = loadWorkbench();
    const context = {
        basePath: '/workbench',
        repositoryId: 'repo-1',
        workbench: {
            defaults: { 'default-limit': '200', 'default-export-format': 'application/n-quads' },
            graphDownloadFormats: [
                { value: 'application/n-triples', label: 'N-Triples' },
                { value: 'application/n-quads', label: 'N-Quads' }
            ]
        }
    };
    const page = metadata => {
        const template = workbench.views.pageTemplate({
            viewId: 'export', vars: [], rows: [], metadata
        }, context, fakeRuntime());
        return visitTemplates(template);
    };
    const initial = page({});
    const initialMarkup = initial.templates.map(item => item.strings.join('')).join('');
    const selectedValue = optionValue => {
        const optionTemplate = initial.templates.find(item => item.strings[0].includes('<option value=')
            && item.values[0] === optionValue);
        return optionTemplate && optionTemplate.values[1];
    };
    assert.equal(selectedValue('application/n-quads'), true, 'the default export format should stay N-Quads');
    assert.equal(selectedValue('100'), true, 'the preview limit should remain independent of the Explore default');
    assert.equal(selectedValue('200'), false, 'the Explore default must not become the export preview default');
    const compression = optionValue => initial.templates.find(item => item.strings.join('').includes('type="radio"')
        && item.strings.join('').includes('name="compression"') && item.values.includes(optionValue));
    const gzip = compression('gzip');
    assert.ok(gzip && gzip.values[gzip.values.indexOf('gzip') + 1] === true, 'compression should default to gzip');
    assert.ok(initial.dynamicValues.includes('Choose Show preview to see the first statements.'));

    const unlimited = page({ 'export-timeout': '0' });
    assert.ok(unlimited.dynamicValues.includes('0'), 'an explicit zero timeout must be preserved');
    const emptyPreview = page({ 'statement-preview-requested': 'true' });
    const emptyText = emptyPreview.templates.flatMap(item => item.strings).join(' ')
        + ' ' + emptyPreview.dynamicValues.join(' ');
    assert.ok(emptyText.includes('No statements to show.'), 'an empty preview should report no results');
    assert.ok(!emptyText.includes('Choose Show preview to see the first statements.'),
        'an empty requested preview should not look like a preview has not been requested');
});
